contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        if (beforeTime == 0) {
            assert(!reverted);
            assert(afterTime == block.timestamp);
            assert(afterBalance == beforeBalance + amount);
        } else {
            assert(!reverted == (block.timestamp > beforeTime));
            if (block.timestamp > beforeTime) {
                assert(afterTime == block.timestamp);
            } else {
                assert(afterTime == beforeTime);
            }
        }
    }

    receive() external payable {}
}

