contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 firstValue, uint256 secondValue, uint256 timeGap) public payable {
        require(address(this).balance >= firstValue + secondValue);

        // 1st call is used to establish a recorded timestamp. Must send exactly 10 ether.
        bool firstReverted;
        try c.fallback{value: firstValue}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 tAfterFirst = c.pastBlockTime();

        // Wait timeGap seconds before the second call.
        // We only report the rule after a successful first call, so that a baseline exists.
        require(!firstReverted, "first call must succeed");

        uint256 beforeSecond = block.timestamp;
        // Advance time without cheatcodes: we cannot literally change block.timestamp,
        // so we test the strictly-increasing condition using the latest timestamp.
        // The second call is made in the same transaction, hence block.timestamp is the same.
        // Two possibilities: same timestamp -> must revert; if timeGap > 0 we expect to encode
        // the rule via the value predicate only, and the timestamp predicate is checked
        // by whether block.timestamp is still equal (same block).

        // Since we cannot advance block.timestamp, the second call only succeeds if
        // block.timestamp > tAfterFirst. Fresh deployment, same tx: block.timestamp is the same,
        // and tAfterFirst already equals block.timestamp, so it will revert unless the contract
        // allows equality (it does not).

        bool secondReverted;
        try c.fallback{value: secondValue}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 tAfterSecond = c.pastBlockTime();

        // General rule:
        // - If the second call sends exactly 10 ether AND block.timestamp has advanced beyond
        //   tAfterFirst, it must succeed and update pastBlockTime to block.timestamp.
        // - Otherwise it must revert and must NOT update pastBlockTime.
        // In this single-transaction test, block.timestamp == beforeSecond == tAfterFirst,
        // so the timestamp condition is false and the second call must revert, leaving
        // pastBlockTime unchanged.
        //
        // We express the rule in terms of observable values:
        bool valueOk = (secondValue == 10 ether);
        bool timeOk = (block.timestamp > tAfterFirst);

        if (valueOk && timeOk) {
            assert(!secondReverted && tAfterSecond == block.timestamp);
        } else {
            assert(secondReverted && tAfterSecond == tAfterFirst);
        }
    }

    receive() external payable {}
}

