    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint tsWait) public payable {
        require(address(this).balance >= amount);

        // Drive c through its public entry so that c.pastBlockTime has a known value.
        // Sending exactly 10 ether is the only way the fallback accepts value.
        if (amount == 10 ether) {
            require(address(this).balance >= 10 ether);
            (bool preOk, ) = address(c).call{value: 10 ether}("");
            require(preOk);
        }

        uint prev = c.pastBlockTime();

        // Ensure the deciding call is made with a non-decreasing timestamp and
        // that its timestamp is strictly greater than the previous one.
        // Use tsWait as the number of seconds to advance (bounded by block.timestamp).
        uint advance = tsWait;
        if (advance > block.timestamp) {
            advance = block.timestamp;
        }
        require(block.timestamp + advance > prev);

        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // General rule: the fallback reverts iff the amount is not exactly 10 ether
        // or the call's timestamp is not strictly greater than the previous one.
        bool wrongValue = (amount != 10 ether);
        bool wrongTime = (block.timestamp + advance <= prev);
        assert(reverted == (wrongValue || wrongTime));

        // On a successful call, pastBlockTime is updated to the call's timestamp.
        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp + advance);
        }
    }

    receive() external payable {}
}

