contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint futureOffset) public payable {
        require(amount <= address(this).balance, "insufficient balance");
        uint beforeTime = c.pastBlockTime();

        bool reverted;
        uint sent = amount;
        try c.fallback{value: sent}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint currentTimestamp = block.timestamp;

        // General rule: fallback reverts exactly when msg.value != 10 ether, or when
        // the timestamp precondition fails. On success, pastBlockTime is updated to
        // the current block timestamp, so afterTime == currentTimestamp and strictly
        // greater than its previous value.
        bool expectedRevert = (sent != 10 ether) || (currentTimestamp <= beforeTime);
        assert(reverted == expectedRevert);
        if (!reverted) {
            assert(afterTime == currentTimestamp && afterTime > beforeTime);
        } else {
            assert(afterTime == beforeTime);
        }
    }

    receive() external payable {}
}

